from jsonb_to_recordset($q$[{"id":4739,"materia":"sus","nivel":0,"enunciado":"A equipe mínima da Estratégia Saúde da Família é formada por:","opcoes":["Médico, enfermeiro, auxiliar ou técnico de enfermagem e agentes comunitários de saúde","Apenas médico e recepcionista","Somente agentes comunitários","Dentista, farmacêutico e assistente social, sem médico nem enfermeiro na equipe"],"explicacao":"A equipe de saúde bucal pode ser incorporada."},{"id":4740,"materia":"sus","nivel":0,"enunciado":"O sistema de informação usado para notificar doenças e agravos é o:","opcoes":["SINAN","SINASC","SIM","SIA"],"explicacao":"SINASC registra nascidos vivos; SIM, óbitos."},{"id":4741,"materia":"sus","nivel":0,"enunciado":"O SIM (Sistema de Informações sobre Mortalidade) é alimentado principalmente pela:","opcoes":["Declaração de óbito","Carteira de vacinação","Ficha de matrícula escolar","Nota fiscal de medicamentos"],"explicacao":"Base para calcular indicadores de mortalidade."},{"id":4742,"materia":"sus","nivel":0,"enunciado":"O SINASC registra informações sobre:","opcoes":["Os nascidos vivos","As internações","As vacinas aplicadas","Os óbitos fetais apenas"],"explicacao":"É alimentado pela Declaração de Nascido Vivo (DNV)."},{"id":4743,"materia":"sus","nivel":0,"enunciado":"O Programa Nacional de Imunizações (PNI) foi criado em:","opcoes":["1973","1990","2003","1950"],"explicacao":"É referência mundial em vacinação pública."},{"id":4744,"materia":"sus","nivel":0,"enunciado":"O Programa Nacional de Segurança do Paciente foi instituído pela:","opcoes":["Portaria nº 529/2013","Lei nº 8.080/1990","Constituição de 1988","Lei nº 7.498/1986"],"explicacao":"Busca reduzir incidentes e danos evitáveis na assistência."},{"id":4745,"materia":"sus","nivel":0,"enunciado":"A Política Nacional de Atenção Integral à Saúde do Homem prioriza a faixa etária de:","opcoes":["20 a 59 anos","0 a 10 anos","60 a 90 anos","Somente adolescentes"],"explicacao":"Homens procuram menos os serviços de atenção primária."},{"id":4746,"materia":"sus","nivel":0,"enunciado":"A Lei nº 10.216/2001, marco da Reforma Psiquiátrica, prioriza:","opcoes":["O tratamento em serviços comunitários, com internação apenas quando os recursos extra-hospitalares forem insuficientes","A internação definitiva em manicômios","O isolamento das pessoas com transtorno mental em hospitais distantes da família e da comunidade","O fim de qualquer atendimento em saúde mental"],"explicacao":"Os CAPS são serviços dessa rede."},{"id":4747,"materia":"sus","nivel":0,"enunciado":"Pelo Estatuto da Pessoa Idosa, é considerada idosa a pessoa com idade igual ou superior a:","opcoes":["60 anos","55 anos","65 anos","70 anos"],"explicacao":"Lei nº 10.741/2003."},{"id":4748,"materia":"sus","nivel":1,"enunciado":"Os CAPS (Centros de Atenção Psicossocial) são:","opcoes":["Serviços comunitários de saúde mental, abertos e de base territorial","Hospitais psiquiátricos de longa permanência, fechados e afastados das cidades","Clínicas privadas de reabilitação","Ambulatórios de cirurgia"],"explicacao":"Fazem parte da Rede de Atenção Psicossocial (RAPS)."},{"id":4749,"materia":"sus","nivel":1,"enunciado":"A Educação Permanente em Saúde se baseia:","opcoes":["Na aprendizagem no trabalho, a partir dos problemas enfrentados no dia a dia dos serviços","Apenas em cursos de pós-graduação no exterior, pagos pelos próprios profissionais de saúde","Em palestras sem relação com a prática","Na formação exclusiva dos médicos"],"explicacao":"Portaria nº 198/2004."},{"id":4750,"materia":"sus","nivel":1,"enunciado":"As equipes multiprofissionais na APS (eMulti) foram instituídas pela:","opcoes":["Portaria nº 635/2023","Lei nº 8.142/1990","Portaria nº 529/2013","Lei nº 10.216/2001"],"explicacao":"Substituíram o antigo modelo de apoio dos NASF."},{"id":4751,"materia":"sus","nivel":1,"enunciado":"Determinantes sociais da saúde são:","opcoes":["Fatores sociais, econômicos, culturais e ambientais que influenciam a saúde das pessoas","Apenas os genes herdados dos pais","Somente o número de hospitais e de leitos de UTI existentes na cidade","Os preços dos remédios nas farmácias"],"explicacao":"Ex.: renda, moradia, escolaridade e saneamento."},{"id":4752,"materia":"sus","nivel":1,"enunciado":"A doença falciforme tem maior frequência na população:","opcoes":["Negra, e a Bahia é o estado com maior incidência","Indígena da região Sul do país","Asiática","Europeia do norte"],"explicacao":"É detectada no teste do pezinho."},{"id":4753,"materia":"sus","nivel":1,"enunciado":"Para o ECA, criança é a pessoa:","opcoes":["Até 12 anos incompletos","Até 18 anos completos","Até 6 anos","Até 15 anos"],"explicacao":"Adolescente: de 12 a 18 anos."},{"id":4754,"materia":"sus","nivel":1,"enunciado":"A hierarquização no SUS significa:","opcoes":["Organizar os serviços em níveis crescentes de complexidade","Dar prioridade aos pacientes que podem pagar pelos serviços","Centralizar tudo no Ministério da Saúde","Atender apenas em hospitais"],"explicacao":"Com referência e contrarreferência entre os níveis."},{"id":4755,"materia":"sus","nivel":2,"enunciado":"A clínica ampliada propõe:","opcoes":["Considerar a doença, a pessoa e seu contexto, com cuidado compartilhado entre profissionais","Focar apenas no exame e no remédio","Atender só casos de alta complexidade","Que cada profissional trabalhe isolado, sem conversar com a equipe sobre os casos"],"explicacao":"Ferramenta da Política Nacional de Humanização."},{"id":4756,"materia":"sus","nivel":2,"enunciado":"O apoio matricial consiste em:","opcoes":["Especialistas darem suporte técnico e pedagógico às equipes de referência","Encaminhar todos os casos para o hospital de referência mais próximo","Contratar médicos temporários","Transferir pacientes entre municípios"],"explicacao":"Amplia a capacidade de resolução da atenção primária."},{"id":4757,"materia":"sus","nivel":2,"enunciado":"A 'tripla carga de doenças' no Brasil corresponde à presença simultânea de:","opcoes":["Doenças infecciosas, doenças crônicas e causas externas, como violência e acidentes","Apenas gripe, resfriado e dengue","Doenças raras, genéticas e alérgicas, sem relação com o modo de vida da população","Somente doenças crônicas"],"explicacao":"Resultado de uma transição epidemiológica incompleta."},{"id":4758,"materia":"sus","nivel":2,"enunciado":"A taxa de mortalidade infantil é calculada dividindo:","opcoes":["Os óbitos de menores de 1 ano pelos nascidos vivos, multiplicado por 1.000","Os óbitos de menores de 5 anos pela população total do município, multiplicado por 100","Os nascimentos pelos óbitos","Os óbitos maternos pelos nascidos vivos"],"explicacao":"É um dos principais indicadores de saúde de uma população."},{"id":4759,"materia":"sus","nivel":3,"enunciado":"Incidência e prevalência diferem porque a incidência mede:","opcoes":["Os casos novos em um período, e a prevalência, todos os casos existentes","Os casos antigos, e a prevalência, os novos","O número de mortes no período, e a prevalência, o número de pessoas que se curaram","A mesma coisa, com nomes diferentes"],"explicacao":"A incidência mostra o risco de adoecer."},{"id":4760,"materia":"sus","nivel":3,"enunciado":"Endemia é:","opcoes":["A ocorrência de uma doença em níveis esperados e constantes em uma região","Um aumento súbito e inesperado de casos acima do esperado para a região em um curto período","Uma epidemia em vários continentes","Um caso isolado de doença rara"],"explicacao":"Pandemia é uma epidemia de alcance mundial."},{"id":4761,"materia":"sus","nivel":3,"enunciado":"A Lei nº 8.080/1990 inclui no campo de atuação do SUS:","opcoes":["A saúde do trabalhador","Apenas a assistência hospitalar","A venda de planos de saúde","O controle das escolas privadas"],"explicacao":"Também a vigilância sanitária, epidemiológica e a assistência farmacêutica."},{"id":4762,"materia":"sus","nivel":4,"enunciado":"O Subsistema de Atenção à Saúde Indígena foi incluído na Lei nº 8.080/1990 pela:","opcoes":["Lei Arouca (Lei nº 9.836/1999)","Lei Áurea","Lei Maria da Penha (Lei nº 11.340/2006)","Lei nº 10.216/2001"],"explicacao":"Organizado em Distritos Sanitários Especiais Indígenas (DSEI)."},{"id":4763,"materia":"sus","nivel":4,"enunciado":"Em um município, houve 30 óbitos de menores de 1 ano e 2.000 nascidos vivos. A taxa de mortalidade infantil é de:","opcoes":["15 por mil nascidos vivos","30 por mil nascidos vivos","1,5 por mil nascidos vivos","66 por mil nascidos vivos"],"explicacao":"30 ÷ 2.000 × 1.000."},{"id":4764,"materia":"enf","nivel":0,"enunciado":"Na via intradérmica, como na vacina BCG, a agulha é introduzida em ângulo de aproximadamente:","opcoes":["15°","90°","45°","60°"],"explicacao":"Forma-se uma pápula na pele."},{"id":4765,"materia":"enf","nivel":0,"enunciado":"O local para injeção intramuscular considerado mais seguro em adultos, por ficar longe de grandes vasos e nervos, é o:","opcoes":["Ventroglúteo (Hochstetter)","Dorsoglúteo, no quadrante superior externo","Bíceps","Antebraço"],"explicacao":"O dorsoglúteo tem risco de lesão do nervo ciático."},{"id":4766,"materia":"enf","nivel":0,"enunciado":"A frequência cardíaca normal de um adulto em repouso é de:","opcoes":["60 a 100 batimentos por minuto","20 a 40 batimentos por minuto","120 a 160 batimentos por minuto","200 batimentos por minuto"],"explicacao":"Abaixo de 60: bradicardia; acima de 100: taquicardia."},{"id":4767,"materia":"enf","nivel":0,"enunciado":"Para medir o comprimento da sonda nasogástrica, mede-se da ponta do nariz:","opcoes":["Ao lóbulo da orelha e daí ao apêndice xifoide","Ao umbigo, passando pela linha média do tórax","Ao queixo","Ao ombro"],"explicacao":"Depois, confirma-se o posicionamento antes de usar a sonda."},{"id":4768,"materia":"enf","nivel":0,"enunciado":"A posição de Sims (lateral esquerda) é usada, por exemplo, para:","opcoes":["Lavagem intestinal (enema)","Punção lombar com o paciente em pé","Parto normal","Exame de vista"],"explicacao":"Facilita a entrada da solução no cólon."},{"id":4769,"materia":"enf","nivel":0,"enunciado":"A sondagem vesical de demora deve ser feita com técnica:","opcoes":["Estéril (asséptica)","Limpa, sem luvas","Sem nenhuma higiene","Com as mãos sem lavar"],"explicacao":"Reduz o risco de infecção urinária associada ao cateter."},{"id":4770,"materia":"enf","nivel":0,"enunciado":"Para limpar uma ferida, a solução mais usada é:","opcoes":["Soro fisiológico a 0,9%","Água sanitária diluída","Álcool puro","Éter"],"explicacao":"Não agride o tecido de cicatrização."},{"id":4771,"materia":"enf","nivel":0,"enunciado":"No calendário de vacinação, a tríplice viral (sarampo, caxumba e rubéola) é aplicada a partir de:","opcoes":["12 meses","2 meses","10 anos","Ao nascer"],"explicacao":"Aos 15 meses aplica-se a tetra viral."},{"id":4772,"materia":"enf","nivel":0,"enunciado":"A vacina contra o rotavírus é aplicada por via:","opcoes":["Oral","Intramuscular","Subcutânea","Intradérmica"],"explicacao":"Protege contra diarreia grave em bebês."},{"id":4773,"materia":"enf","nivel":0,"enunciado":"A vacina pentavalente é aplicada aos:","opcoes":["2, 4 e 6 meses","9, 12 e 15 meses","Ao nascer, apenas","10, 20 e 30 anos"],"explicacao":"Protege contra difteria, tétano, coqueluche, hepatite B e Haemophilus influenzae b."},{"id":4774,"materia":"enf","nivel":0,"enunciado":"Pela regra de Naegele, para DUM em 10 de março, a data provável do parto é:","opcoes":["17 de dezembro","10 de dezembro","17 de novembro","3 de dezembro"],"explicacao":"Somam-se 7 dias e diminuem-se 3 meses (passando para o ano seguinte, quando for o caso)."},{"id":4775,"materia":"enf","nivel":0,"enunciado":"Hipotermia é a temperatura corporal:","opcoes":["Abaixo de 35 °C","Entre 36 e 37 °C","Acima de 38 °C","Exatamente 37 °C"],"explicacao":"Pode ocorrer em idosos, recém-nascidos e em exposição ao frio."},{"id":4776,"materia":"enf","nivel":0,"enunciado":"Vermelhidão, calor, dor e cordão endurecido no trajeto de uma veia puncionada sugerem:","opcoes":["Flebite","Infiltração de ar","Hipoglicemia","Reação alérgica sistêmica"],"explicacao":"Deve-se retirar o cateter e puncionar outro local."},{"id":4777,"materia":"enf","nivel":0,"enunciado":"A vacina contra a febre amarela, no calendário infantil, é aplicada aos:","opcoes":["9 meses","2 meses","Ao nascer","15 anos"],"explicacao":"Com reforço aos 4 anos."},{"id":4778,"materia":"enf","nivel":0,"enunciado":"Na injeção subcutânea, como a de insulina, a agulha curta costuma ser introduzida em ângulo de:","opcoes":["90°","15°","5°","180°"],"explicacao":"Em pessoas muito magras, pode-se usar 45° com prega cutânea."},{"id":4779,"materia":"enf","nivel":0,"enunciado":"O tecido de granulação, sinal de boa cicatrização, tem aspecto:","opcoes":["Vermelho vivo e granuloso","Preto e seco","Amarelo, úmido e com odor fétido","Branco e duro"],"explicacao":"Tecido preto e seco é necrose (escara)."},{"id":4780,"materia":"enf","nivel":0,"enunciado":"O cateter nasal de oxigênio é usado, em geral, com fluxo de até cerca de:","opcoes":["6 L/min","20 L/min","50 L/min","100 L/min"],"explicacao":"Fluxos maiores ressecam a mucosa e pouco aumentam a oferta de oxigênio."},{"id":4781,"materia":"enf","nivel":1,"enunciado":"A heparina tem 5.000 UI/mL. A prescrição é de 2.500 UI. Devem ser aspirados:","opcoes":["0,5 mL","5 mL","2,5 mL","0,25 mL"],"explicacao":"2.500 ÷ 5.000 = 0,5."},{"id":4782,"materia":"enf","nivel":1,"enunciado":"Na seringa de insulina U-100, 20 UI correspondem a:","opcoes":["0,2 mL","2 mL","20 mL","0,02 mL"],"explicacao":"1 mL = 100 UI."},{"id":4783,"materia":"enf","nivel":1,"enunciado":"Para infundir 500 mL em 6 horas com macrogotas, o gotejamento é de aproximadamente:","opcoes":["28 gotas/min","83 gotas/min","14 gotas/min","50 gotas/min"],"explicacao":"500 ÷ (6 × 3) ≈ 27,8."},{"id":4784,"materia":"enf","nivel":1,"enunciado":"Para infundir 250 mL em 5 horas com microgotas, o gotejamento é de:","opcoes":["50 microgotas/min","25 microgotas/min","125 microgotas/min","15 microgotas/min"],"explicacao":"250 ÷ 5."},{"id":4785,"materia":"enf","nivel":1,"enunciado":"Em 500 mL de soro glicosado a 5%, há:","opcoes":["25 g de glicose","5 g de glicose","50 g de glicose","2,5 g de glicose"],"explicacao":"5 g a cada 100 mL."},{"id":4786,"materia":"enf","nivel":1,"enunciado":"O frasco coletor do dreno de tórax deve ficar:","opcoes":["Sempre abaixo do nível do tórax do paciente","Acima da cabeça do paciente","Sobre a cama, ao lado do paciente, na altura do ombro","Pendurado no suporte de soro"],"explicacao":"Evita o refluxo do líquido para a cavidade pleural."},{"id":4787,"materia":"enf","nivel":1,"enunciado":"Paciente com bactéria multirresistente na ferida exige precaução:","opcoes":["De contato, com luvas e avental","Apenas por aerossóis","Nenhuma, se estiver sem febre","Somente com máscara cirúrgica no paciente"],"explicacao":"Também quarto privativo ou coorte, quando possível."},{"id":4788,"materia":"enf","nivel":1,"enunciado":"Na glicemia capilar, a punção é feita preferencialmente:","opcoes":["Na lateral da ponta do dedo","No centro da palma da mão","No lóbulo da orelha, em qualquer paciente adulto","No dedo do pé em adultos"],"explicacao":"A lateral é menos dolorosa."},{"id":4789,"materia":"enf","nivel":1,"enunciado":"A colostomia é:","opcoes":["Uma abertura do intestino grosso na parede do abdome","Uma sonda colocada no estômago pela boca","Um corte na traqueia","Um cateter na bexiga"],"explicacao":"A ileostomia é feita no intestino delgado."},{"id":4790,"materia":"enf","nivel":1,"enunciado":"Os lóquios, no puerpério, mudam de cor na seguinte ordem:","opcoes":["Rubros (vermelhos), serosos e alvos (esbranquiçados)","Alvos, serosos e rubros","Verdes, amarelos e vermelhos","Sempre vermelhos e abundantes até o 40º dia após o parto"],"explicacao":"Odor fétido pode indicar infecção."},{"id":4791,"materia":"enf","nivel":1,"enunciado":"Na suspeita de reação transfusional, a primeira conduta é:","opcoes":["Interromper a transfusão e manter o acesso venoso com soro fisiológico","Acelerar o gotejamento","Trocar a bolsa por outra do mesmo doador e continuar a infusão","Aguardar o fim da bolsa"],"explicacao":"Depois, comunicar o médico e o serviço de hemoterapia."},{"id":4792,"materia":"enf","nivel":1,"enunciado":"Na escala SAMU usada para reconhecer AVC, avalia-se:","opcoes":["Sorriso, abraço, música (fala) e urgência para chamar socorro","Sono, apetite, memória e urina","Saturação, altura, massa corporal e umidade da pele do paciente","Sede, ardor, mancha e unha"],"explicacao":"Desvio da boca, fraqueza em um braço e fala enrolada são sinais de alerta."},{"id":4793,"materia":"enf","nivel":2,"enunciado":"Na prova do laço, em adulto com suspeita de dengue, o resultado é positivo quando aparecem:","opcoes":["20 ou mais petéquias em um quadrado de 2,5 cm de lado","2 petéquias no braço todo","Vermelhidão no local do manguito logo após desinflar","Dor ao inflar o manguito"],"explicacao":"Em crianças, 10 ou mais."},{"id":4794,"materia":"enf","nivel":2,"enunciado":"Dor no peito em aperto, que irradia para o braço esquerdo, com suor frio, sugere:","opcoes":["Infarto agudo do miocárdio","Crise de ansiedade, sempre","Gastrite leve","Torcicolo"],"explicacao":"Exige atendimento imediato e eletrocardiograma rápido."},{"id":4795,"materia":"enf","nivel":2,"enunciado":"No choque hipovolêmico, são sinais esperados:","opcoes":["Taquicardia, hipotensão, pele fria e pálida","Bradicardia e pele quente","Pressão alta, face avermelhada e pele quente e seca","Febre alta e tosse"],"explicacao":"Causado por perda de sangue ou de líquidos."},{"id":4796,"materia":"enf","nivel":2,"enunciado":"Os critérios do qSOFA para identificar risco de sepse incluem:","opcoes":["Frequência respiratória ≥ 22, pressão sistólica ≤ 100 mmHg e alteração do nível de consciência","Febre acima de 39 °C, tosse produtiva e dor de garganta há mais de três dias","Dor de cabeça e coriza","Glicemia baixa e sede"],"explicacao":"Dois ou mais critérios indicam maior risco de evolução grave."},{"id":4797,"materia":"enf","nivel":2,"enunciado":"O tratamento diretamente observado (TDO), na tuberculose, consiste em:","opcoes":["Um profissional acompanhar a pessoa tomando o remédio","Fazer raio-X todos os dias","Internar todos os pacientes","Trocar o remédio a cada semana para evitar a resistência do bacilo"],"explicacao":"Aumenta a adesão e a cura."},{"id":4798,"materia":"enf","nivel":2,"enunciado":"A avaliação do pé diabético para perda de sensibilidade protetora usa o:","opcoes":["Monofilamento de 10 g","Termômetro digital infravermelho","Esfigmomanômetro","Estetoscópio"],"explicacao":"Pé sem sensibilidade tem alto risco de úlcera."},{"id":4799,"materia":"enf","nivel":2,"enunciado":"Em 500 mL de soro fisiológico a 0,9%, há:","opcoes":["4,5 g de cloreto de sódio","0,9 g de cloreto de sódio","9 g de cloreto de sódio","45 g de cloreto de sódio"],"explicacao":"0,9 g a cada 100 mL."},{"id":4800,"materia":"enf","nivel":2,"enunciado":"Na escala numérica de dor, a pessoa classifica a intensidade de:","opcoes":["0 (sem dor) a 10 (pior dor imaginável)","1 a 3 apenas","A a E","0 a 100 graus, como um termômetro"],"explicacao":"A dor é considerada o 5º sinal vital."},{"id":4801,"materia":"enf","nivel":3,"enunciado":"Uma gasometria com pH 7,25 e PaCO₂ de 60 mmHg indica:","opcoes":["Acidose respiratória","Alcalose metabólica","Alcalose respiratória","Valores normais"],"explicacao":"pH baixo com CO₂ alto: o problema é respiratório."},{"id":4802,"materia":"enf","nivel":3,"enunciado":"O cloreto de potássio concentrado nunca deve ser administrado:","opcoes":["Em bolus (direto na veia, sem diluição)","Diluído em soro","Por bomba de infusão","Com prescrição médica e diluído em soro, em infusão lenta"],"explicacao":"Pode causar parada cardíaca. É medicamento de alta vigilância."},{"id":4803,"materia":"enf","nivel":3,"enunciado":"Na hanseníase, a avaliação neurológica simplificada inclui testar a sensibilidade com:","opcoes":["Monofilamentos (estesiômetro) em mãos e pés","Termômetro de mercúrio e algodão com álcool","Reflexo patelar apenas","Fita métrica"],"explicacao":"Previne incapacidades físicas."},{"id":4804,"materia":"enf","nivel":3,"enunciado":"Prescrição: 1.000 mL de soro fisiológico em 12 horas, em bomba de infusão. A vazão programada é de aproximadamente:","opcoes":["83 mL/h","12 mL/h","120 mL/h","42 mL/h"],"explicacao":"1.000 ÷ 12."},{"id":4805,"materia":"enf","nivel":4,"enunciado":"Uma paciente pesa 60 kg e precisa de 0,1 mg/kg de morfina. A ampola tem 10 mg/mL. O volume a aspirar é de:","opcoes":["0,6 mL","6 mL","1 mL","0,06 mL"],"explicacao":"0,1 × 60 = 6 mg; 6 ÷ 10 = 0,6 mL."},{"id":4806,"materia":"enf","nivel":4,"enunciado":"Em paciente com AVC isquêmico, a trombólise venosa costuma ser indicada se iniciada em até:","opcoes":["4,5 horas do início dos sintomas","48 horas do início dos sintomas","7 dias","1 mês"],"explicacao":"Por isso é essencial saber o horário em que os sintomas começaram."},{"id":4807,"materia":"enf","nivel":4,"enunciado":"Uma gasometria com pH 7,50 e bicarbonato de 32 mEq/L indica:","opcoes":["Alcalose metabólica","Acidose respiratória","Acidose metabólica","Valores normais"],"explicacao":"Pode ocorrer com vômitos repetidos."},{"id":4808,"materia":"enf","nivel":4,"enunciado":"Em adulto em parada cardiorrespiratória com fibrilação ventricular (ritmo chocável), além de manter a RCP de boa qualidade, a prioridade é:","opcoes":["Desfibrilar o mais rápido possível","Esperar o resultado de exames de sangue","Fazer apenas ventilações, sem compressões","Administrar insulina"],"explicacao":"Cada minuto sem desfibrilação reduz muito a chance de sobrevivência."},{"id":4809,"materia":"med","nivel":0,"enunciado":"O diagnóstico de hipertensão arterial deve ser confirmado com:","opcoes":["Medidas elevadas em pelo menos duas ocasiões diferentes","Uma única medida alta","Apenas um exame de sangue com colesterol","Raio-X de tórax"],"explicacao":"Monitorização residencial (MRPA) ou ambulatorial (MAPA) ajudam a confirmar."},{"id":4810,"materia":"med","nivel":0,"enunciado":"Na sífilis, o VDRL é um teste:","opcoes":["Não treponêmico, útil também para acompanhar o tratamento","Treponêmico que fica positivo para sempre, sem servir para o acompanhamento","De imagem","Genético"],"explicacao":"Os testes treponêmicos, como o teste rápido, costumam permanecer positivos."},{"id":4811,"materia":"med","nivel":0,"enunciado":"Na dengue sem sinais de alarme e sem comorbidades (grupo A), a conduta é:","opcoes":["Hidratação oral e acompanhamento ambulatorial","Internação em UTI","Antibiótico de amplo espectro","Ácido acetilsalicílico e anti-inflamatórios para a dor"],"explicacao":"AAS e anti-inflamatórios devem ser evitados na dengue."},{"id":4812,"materia":"med","nivel":0,"enunciado":"TSH elevado com T4 livre baixo sugere:","opcoes":["Hipotireoidismo primário","Hipertireoidismo por doença de Graves","Diabetes","Anemia"],"explicacao":"A tireoide produz pouco hormônio e a hipófise aumenta o TSH."},{"id":4813,"materia":"med","nivel":0,"enunciado":"Os princípios clássicos da bioética são:","opcoes":["Autonomia, beneficência, não maleficência e justiça","Lucro, rapidez, sigilo e fama","Obediência, hierarquia e disciplina","Universalidade, equidade, integralidade e participação da comunidade"],"explicacao":"Os do último item são princípios do SUS."},{"id":4814,"materia":"med","nivel":0,"enunciado":"Dor no quadrante inferior direito do abdome com sinal de Blumberg positivo sugere:","opcoes":["Apendicite aguda","Colecistite calculosa","Pancreatite aguda","Infarto agudo do miocárdio"],"explicacao":"Blumberg: dor à descompressão brusca."},{"id":4815,"materia":"med","nivel":1,"enunciado":"O sinal de Murphy positivo sugere:","opcoes":["Colecistite aguda","Apendicite aguda","Pneumonia lobar","Cistite simples"],"explicacao":"Interrupção da inspiração à palpação do ponto da vesícula."},{"id":4816,"materia":"med","nivel":1,"enunciado":"A ferritina baixa é um achado típico da:","opcoes":["Anemia ferropriva","Anemia falciforme","Leucemia","Anemia por falta de vitamina B12"],"explicacao":"Reflete os estoques de ferro do organismo."},{"id":4817,"materia":"med","nivel":1,"enunciado":"O PHQ-9 é um questionário usado para rastrear:","opcoes":["Depressão","Diabetes","Hipertensão","Asma"],"explicacao":"Útil na atenção primária."},{"id":4818,"materia":"med","nivel":1,"enunciado":"No tratamento da faringite bacteriana estreptocócica, uma opção de primeira linha é a:","opcoes":["Penicilina benzatina ou amoxicilina","Azitromicina para todos os casos virais","Insulina","Corticoide isolado"],"explicacao":"A maioria das dores de garganta é viral e não precisa de antibiótico."},{"id":4819,"materia":"med","nivel":1,"enunciado":"Na abordagem ao tabagismo recomendada pelo Ministério da Saúde (PAAPA), a primeira etapa é:","opcoes":["Perguntar se a pessoa fuma","Prescrever medicamento","Encaminhar ao especialista","Fazer raio-X de tórax"],"explicacao":"Depois: avaliar, aconselhar, preparar e acompanhar."},{"id":4820,"materia":"med","nivel":2,"enunciado":"Disúria, aumento da frequência urinária e urgência, sem febre, em mulher jovem, sugerem:","opcoes":["Cistite (infecção urinária baixa)","Pielonefrite grave","Cálculo renal obstrutivo com necessidade de cirurgia, sempre","Insuficiência cardíaca"],"explicacao":"Febre e dor lombar sugerem pielonefrite."},{"id":4821,"materia":"med","nivel":2,"enunciado":"O sigilo médico, pelo Código de Ética Médica, pode ser quebrado:","opcoes":["Por motivo justo, dever legal ou consentimento por escrito do paciente","A pedido de qualquer parente","Quando o empregador ou o plano de saúde solicitar","Nunca, nem por dever legal"],"explicacao":"Ex.: notificação compulsória é dever legal."},{"id":4822,"materia":"med","nivel":3,"enunciado":"Uma doença tem prevalência de 1% e o teste tem especificidade de 90%. Em 1.000 pessoas sem a doença testadas, esperam-se cerca de:","opcoes":["100 falsos positivos","10 falsos positivos","900 falsos positivos","1 falso positivo"],"explicacao":"10% de 1.000 = 100. Por isso rastrear doenças raras gera muitos falsos positivos."},{"id":4823,"materia":"med","nivel":4,"enunciado":"Em pessoa com diabetes, hipertensão e albuminúria, a classe de anti-hipertensivo preferida, por proteger os rins, é:","opcoes":["IECA ou BRA (ex.: enalapril ou losartana)","Betabloqueador isolado","Diurético de alça como única opção","Nenhum, pois não se trata a pressão no diabetes"],"explicacao":"Reduzem a progressão da doença renal do diabetes. Não se associam IECA e BRA."},{"id":4824,"materia":"fisio","nivel":0,"enunciado":"A escala de Borg é usada para medir:","opcoes":["A percepção subjetiva de esforço","A força de preensão","O equilíbrio","A amplitude articular do ombro e do quadril"],"explicacao":"Ajuda a controlar a intensidade do exercício."},{"id":4825,"materia":"fisio","nivel":0,"enunciado":"O teste de caminhada de 6 minutos avalia:","opcoes":["A capacidade funcional ao exercício","A visão","A audição e o equilíbrio vestibular","A memória"],"explicacao":"Muito usado em doenças cardíacas e pulmonares."},{"id":4826,"materia":"fisio","nivel":0,"enunciado":"Na lombalgia inespecífica, a recomendação atual é:","opcoes":["Manter-se ativo e fazer exercícios, evitando repouso prolongado","Repouso absoluto por semanas","Imobilizar a coluna com colete rígido por vários meses","Evitar qualquer movimento"],"explicacao":"O repouso prolongado atrasa a recuperação."},{"id":4827,"materia":"fisio","nivel":0,"enunciado":"O teste de Phalen é usado para investigar:","opcoes":["Síndrome do túnel do carpo","Lesão do ligamento cruzado","Hérnia de disco lombar","Entorse de tornozelo"],"explicacao":"Flexão mantida do punho reproduz os sintomas."},{"id":4828,"materia":"fisio","nivel":0,"enunciado":"O teste de Thompson avalia a integridade do:","opcoes":["Tendão de Aquiles (calcâneo)","Manguito rotador","Ligamento colateral medial do joelho","Menisco"],"explicacao":"Ao apertar a panturrilha, o pé não se move se houver ruptura."},{"id":4829,"materia":"fisio","nivel":1,"enunciado":"A capsulite adesiva ('ombro congelado') causa principalmente:","opcoes":["Perda progressiva da amplitude de movimento do ombro, com dor","Fratura de clavícula após queda","Luxação recorrente","Lesão no cotovelo"],"explicacao":"Mais comum em pessoas com diabetes."},{"id":4830,"materia":"fisio","nivel":1,"enunciado":"O teste de McMurray é usado para avaliar lesão de:","opcoes":["Menisco do joelho","Tendão de Aquiles","Ombro","Coluna cervical"],"explicacao":"Um estalido doloroso sugere lesão meniscal."},{"id":4831,"materia":"fisio","nivel":1,"enunciado":"Após amputação, o enfaixamento compressivo do coto serve para:","opcoes":["Reduzir o edema e moldar o coto para a prótese","Aumentar o inchaço","Impedir a cicatrização e aumentar a dor fantasma","Esquentar a região"],"explicacao":"Feito em forma de oito, com pressão maior na extremidade."},{"id":4832,"materia":"fisio","nivel":1,"enunciado":"Após um AVC, o membro superior afetado costuma assumir padrão de:","opcoes":["Flexão (cotovelo, punho e dedos dobrados)","Extensão total","Abdução máxima do ombro","Rotação externa completa do ombro com extensão dos dedos"],"explicacao":"Relacionado à espasticidade."},{"id":4833,"materia":"fisio","nivel":2,"enunciado":"A drenagem postural usa:","opcoes":["A gravidade, com posições específicas, para ajudar a eliminar secreções pulmonares","Apenas aparelhos elétricos","Exercícios de força para as pernas, com carga progressiva","Gelo no tórax"],"explicacao":"Pode ser associada a técnicas de higiene brônquica."},{"id":4834,"materia":"fisio","nivel":2,"enunciado":"A classificação GMFCS é usada em crianças com paralisia cerebral para:","opcoes":["Classificar a função motora grossa, em cinco níveis","Medir a inteligência","Avaliar a visão","Calcular a dose de medicamento antiespástico pelo peso"],"explicacao":"Ajuda a prever e planejar a reabilitação."},{"id":4835,"materia":"fisio","nivel":2,"enunciado":"A sarcopenia, comum em idosos, é:","opcoes":["A perda de massa e força muscular","O aumento da massa óssea causado pelo exercício","Uma infecção de pele","Um tipo de artrite"],"explicacao":"Exercícios resistidos ajudam a preveni-la."},{"id":4836,"materia":"fisio","nivel":3,"enunciado":"A posição prona é usada em pacientes com síndrome do desconforto respiratório agudo (SDRA) porque:","opcoes":["Melhora a oxigenação, ao redistribuir a ventilação pulmonar","Reduz a necessidade de qualquer monitorização e de ventilação mecânica","Cura a infecção","Diminui a frequência cardíaca"],"explicacao":"Muito usada na pandemia de covid-19."},{"id":4837,"materia":"fisio","nivel":3,"enunciado":"A FES (estimulação elétrica funcional) é usada para:","opcoes":["Provocar contração muscular durante uma tarefa funcional, como a marcha","Aliviar apenas a dor crônica, sem produzir contração muscular","Aquecer tecidos profundos","Diagnosticar fraturas"],"explicacao":"Muito usada em lesões neurológicas."},{"id":4838,"materia":"fisio","nivel":4,"enunciado":"Na reabilitação cardíaca, a frequência cardíaca de treino costuma ser calculada pela fórmula de Karvonen, que usa:","opcoes":["A frequência de reserva (máxima menos repouso)","Apenas o peso do paciente","A pressão arterial diastólica medida após o exercício","A altura do paciente"],"explicacao":"FC treino = FC repouso + % × (FC máx − FC repouso)."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('sus','enf','fisio','med') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
